import{rng,createModel,evaluate}from './inverse-network.mjs';
export{evaluate};
const K=2*Math.PI;
export const wave=(x,t,v,D)=>.5+.4*Math.exp(-K*K*D*t)*Math.sin(K*(x-v*t));
export function validate(c){if(!c||!Number.isInteger(c.seed)||c.seed<1||c.seed>9999||![8,16,32,64].includes(c.samples)||![0,.01,.03].includes(c.noise)||![1000,3000,6000].includes(c.steps)||!['spread','initial'].includes(c.design))throw Error('Use the supported experiment settings.');return c;}
export function generate(c){validate(c);const r=rng(c.seed+50000),truth={v:-.7+1.4*r(),D:.004+.026*r()},obs=Array.from({length:c.samples},()=>{const x=r(),t=c.design==='initial'?0:.05+.35*r();return{x,t,y:wave(x,t,truth.v,truth.D)+c.noise*(r()+r()+r()+r()+r()+r()-3)*Math.sqrt(2)};});return{truth,obs};}
export function adam(m,g,lr=.003){const n=++m.iteration,b1=1-.9**n,b2=1-.999**n;for(let i=0;i<g.length;i++){m.m[i]=.9*m.m[i]+.1*g[i];m.v[i]=.999*m.v[i]+.001*g[i]*g[i];m.p[i]-=lr*(m.m[i]/b1)/(Math.sqrt(m.v[i]/b2)+1e-8);}}
export function objective(p,obs,pts,v,D,weight=0){const g=new Float64Array(p.length);let data=0,initial=0,physics=0,gv=0,glogD=0;for(const [items,key]of[[obs,'data'],[Array.from({length:32},(_,i)=>({x:(i+.5)/32,t:0,y:wave((i+.5)/32,0,0,0)})),'initial']])for(const q of items){const e=evaluate(p,q.x,q.t,true,v,D),d=e.u-q.y;if(key==='data')data+=d*d/items.length;else initial+=d*d/items.length;for(let i=0;i<g.length;i++)g[i]+=2*d*e.gu[i]/items.length;}for(const q of pts){const e=evaluate(p,q.x,q.t,weight>0,v,D);physics+=e.r*e.r/pts.length;if(weight){for(let i=0;i<g.length;i++)g[i]+=2*weight*e.r*e.gr[i]/pts.length;gv+=2*weight*e.r*e.ux/pts.length;glogD-=2*weight*e.r*e.uxx*D/pts.length;}}return{g,gv,glogD,data,initial,physics,total:data+initial+weight*physics};}
export function createTraining(obs,seed){return{obs:obs.map(q=>({...q})),nn:createModel(seed),pinn:createModel(seed),parameters:{p:new Float64Array([0,Math.log(.015)]),m:new Float64Array(2),v:new Float64Array(2),iteration:0},random:rng(seed+8000),step:0};}
export function step(ex){const pts=Array.from({length:32},()=>({x:ex.random(),t:ex.random()})),v=ex.parameters.p[0],D=Math.exp(ex.parameters.p[1]);const a=objective(ex.nn.p,ex.obs,pts,v,D,0),b=objective(ex.pinn.p,ex.obs,pts,v,D,.1);adam(ex.nn,a.g);adam(ex.pinn,b.g);adam(ex.parameters,[b.gv,b.glogD],.002);ex.parameters.p[0]=Math.max(-1,Math.min(1,ex.parameters.p[0]));ex.parameters.p[1]=Math.max(Math.log(.001),Math.min(Math.log(.05),ex.parameters.p[1]));ex.step++;return{nn:a.total,pinn:b.total};}
export function fitClassical(obs,noise){const mse=(v,D)=>obs.reduce((s,p)=>s+(wave(p.x,p.t,v,D)-p.y)**2,0)/obs.length;const grid=[];let best={mse:Infinity};for(let i=0;i<=80;i++)for(let j=0;j<=49;j++){const v=-1+i/40,D=.001+j*.001,q={v,D,mse:mse(v,D)};grid.push(q);if(q.mse<best.mse)best=q;}let dv=.025,dd=.001;for(let n=0;n<10;n++){let next=best;for(const a of[-1,0,1])for(const b of[-1,0,1]){const v=Math.max(-1,Math.min(1,best.v+a*dv)),D=Math.max(.001,Math.min(.05,best.D+b*dd)),q={v,D,mse:mse(v,D)};if(q.mse<next.mse)next=q;}best=next;dv/=2;dd/=2;}
const sensitivity=[...grid];for(let i=-20;i<=20;i++)for(let j=-20;j<=20;j++){const v=Math.max(-1,Math.min(1,best.v+i*.0025)),D=Math.max(.001,Math.min(.05,best.D+j*.00025));sensitivity.push({v,D,mse:mse(v,D)});}const tolerance=Math.max(1e-5,2*noise*noise/obs.length),near=sensitivity.filter(q=>q.mse<=best.mse+tolerance);const set=[...near,best];return{...best,range:{v:[Math.min(...set.map(q=>q.v)),Math.max(...set.map(q=>q.v))],D:[Math.min(...set.map(q=>q.D)),Math.max(...set.map(q=>q.D))]},tolerance,grid: grid.map(q=>q.mse),nonIdentifiable:obs.every(q=>q.t===0)};}
export function score(predict,truth){let squared=0,n=0,massError=0;for(let ti=0;ti<=20;ti++){const t=ti/20;let mass=0;for(let xi=0;xi<64;xi++){const x=(xi+.5)/64,u=predict(x,t);mass+=u/64;if(t>.4){squared+=(u-wave(x,t,truth.v,truth.D))**2;n++;}}massError=Math.max(massError,Math.abs(mass-.5));}return{forecastRMSE:Math.sqrt(squared/n),massError};}
export function exportModel(ex,fit,config){return{format:'transport-hidden-v1',config,architecture:'32 tanh neurons; sin(2πx), cos(2πx), 2t−1 inputs; bias then 32 [output,sin,cos,time,bias] groups',domain:{x:[0,1],t:[0,1]},knownInitial:'0.5 + 0.4 sin(2πx)',boundary:'periodic',nn:Array.from(ex.nn.p),pinn:Array.from(ex.pinn.p),parameters:{v:ex.parameters.p[0],D:Math.exp(ex.parameters.p[1])},classical:{v:fit.v,D:fit.D},trainedSteps:ex.step,observations:ex.obs};}
export function predictModel(model,kind,x,t){if(model?.format!=='transport-hidden-v1'||!['nn','pinn','classical'].includes(kind)||!Number.isFinite(x)||!Number.isFinite(t)||x<0||x>1||t<0||t>1)throw Error('Invalid model or query.');if(kind==='classical')return wave(x,t,model.classical.v,model.classical.D);const p=model[kind];if(!Array.isArray(p)||p.length!==161||!p.every(Number.isFinite))throw Error('Invalid model weights.');return evaluate(p,x,t).u;}
